-- Catalogue extensible GA TCG / schema sans cout de construction de deck.
create table if not exists public.tcg_cards_v2 (
 id text primary key,
 character_slug text not null,
 name text not null,
 rarity text not null check (rarity in ('common','uncommon','rare','ultra','secret')),
 faction text not null,
 attack integer not null check (attack between 0 and 30),
 guard integer not null check (guard between 0 and 30),
 power integer not null check (power between 1 and 15),
 damage integer not null check (damage between 1 and 12),
 ability_type text not null,
 ability_params jsonb not null default '{}'::jsonb,
 faction_bonus numeric not null default 2,
 legacy_duel_cost integer not null default 1 check (legacy_duel_cost between 1 and 9),
 art_url text,
 publication_status text not null default 'draft' check (publication_status in ('draft','test','published')),
 booster_ids text[] not null default array[]::text[],
 role text not null default 'versatile',
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
alter table public.tcg_cards_v2 enable row level security;
revoke all on public.tcg_cards_v2 from anon, authenticated;
grant select on public.tcg_cards_v2 to authenticated;
drop policy if exists tcg_cards_v2_published on public.tcg_cards_v2;
create policy tcg_cards_v2_published on public.tcg_cards_v2 for select to authenticated using(publication_status='published');
create index if not exists tcg_cards_v2_publication_rarity on public.tcg_cards_v2(publication_status,rarity);
create index if not exists tcg_cards_v2_booster_ids on public.tcg_cards_v2 using gin(booster_ids);
create table if not exists public.tcg_booster_types_v2 (
 id text primary key,
 name text not null,
 sigil text not null,
 lead_slug text,
 pool_slugs text[] not null default array[]::text[],
 secret_only_slug text,
 published boolean not null default true
);
alter table public.tcg_booster_types_v2 enable row level security;
revoke all on public.tcg_booster_types_v2 from anon,authenticated;
grant select on public.tcg_booster_types_v2 to authenticated;
drop policy if exists tcg_booster_types_v2_read on public.tcg_booster_types_v2;
create policy tcg_booster_types_v2_read on public.tcg_booster_types_v2 for select to authenticated using (published);
create table if not exists public.tcg_slot_odds_v2 (
 slot integer primary key check (slot between 0 and 4),
 odds jsonb not null check (jsonb_typeof(odds)='object')
);
alter table public.tcg_slot_odds_v2 enable row level security;
revoke all on public.tcg_slot_odds_v2 from anon,authenticated;
grant select on public.tcg_slot_odds_v2 to authenticated;
drop policy if exists tcg_slot_odds_v2_read on public.tcg_slot_odds_v2;
create policy tcg_slot_odds_v2_read on public.tcg_slot_odds_v2 for select to authenticated using(true);
 on conflict(slot) do nothing;
